sys_script_include.script:
var PatientHandoffService = Class.create();

PatientHandoffService.prototype = {

    initialize: function() {
        this.validationUtils = new ValidationUtils();
    },

    /**
     * Check whether a Patient Handoff record exists.
     *
     * @param {String} handoffSysId
     * @return {Boolean}
     */
    handoffExists: function(handoffSysId) {

        if (this.validationUtils.isEmpty(handoffSysId)) {
            return false;
        }

        var handoff = new GlideRecord(
            'x_2130921_caresy_0_patient_handoff'
        );

        if (!handoff.isValid()) {
            gs.error(
                'PatientHandoffService: Patient Handoff table is invalid.'
            );
            return false;
        }

        return handoff.get(handoffSysId);
    },

    /**
     * Retrieve a Patient Handoff record.
     *
     * @param {String} handoffSysId
     * @return {GlideRecord|null}
     */
    getHandoff: function(handoffSysId) {

        if (this.validationUtils.isEmpty(handoffSysId)) {
            return null;
        }

        var handoff = new GlideRecord(
            'x_2130921_caresy_0_patient_handoff'
        );

        if (!handoff.isValid()) {
            gs.error(
                'PatientHandoffService: Patient Handoff table is invalid.'
            );
            return null;
        }

        if (handoff.get(handoffSysId)) {
            return handoff;
        }

        return null;
    },

    /**
     * Check whether a Patient Handoff is currently active.
     *
     * @param {String} handoffSysId
     * @return {Boolean}
     */
    isHandoffActive: function(handoffSysId) {

        var handoff = this.getHandoff(handoffSysId);

        if (!handoff) {
            return false;
        }

        return handoff.getValue('active') == '1';
    },

    type: 'PatientHandoffService'
};
